/* @lc app=leetcode id=3892 lang=kotlin */ class Solution { fun lin(c: List<Long>, k: Int): Long = c.fold(Pair(LongArray(k + 1) { if (it == 0) 0L else 1_000_000_000_000_000_000L }, LongArray(k + 1) { 1_000_000_000_000_000_000L })) { (f0, f1), x -> Pair(LongArray(k + 1) { j -> minOf(f0[j], f1[j]) }, LongArray(k + 1) { j -> if (j > 0 && f0[j - 1] < 1_000_000_000_000_000_000L) f0[j - 1] + x else 1_000_000_000_000_000_000L }) }.let { (f0, f1) -> minOf(f0[k], f1[k]) } fun minOperations(nums: IntArray, k: Int): Int = nums.size.let { n -> if (k > n / 2) -1 else if (k == 0) 0 else nums.indices.map { i -> maxOf(0L, maxOf(nums[(i + n - 1) % n], nums[(i + 1) % n]).toLong() + 1 - nums[i]) }.let { c -> minOf(lin(c.drop(1), k), c[0] + (if (k >= 1) lin(c.drop(2).dropLast(1), k - 1) else 0L)).toInt() } } }